  Sprite PanelSprite(bool circle=false){string key=circle?"native-circle":"native-rounded";if(!sprites.TryGetValue(key,out var sprite)){var texture=new Texture2D(64,64,TextureFormat.RGBA32,false);var pixels=new Color32[4096];for(int y=0;y<64;y++)for(int x=0;x<64;x++){float dx=Mathf.Max(12-x,Mathf.Max(0,x-51)),dy=Mathf.Max(12-y,Mathf.Max(0,y-51));pixels[y*64+x]=new Color32(255,255,255,(byte)(255*Mathf.Clamp01(circle?31.5f-Mathf.Sqrt((x-31.5f)*(x-31.5f)+(y-31.5f)*(y-31.5f)):12.5f-Mathf.Sqrt(dx*dx+dy*dy))));}texture.SetPixels32(pixels);texture.Apply();sprite=Sprite.Create(texture,new Rect(0,0,64,64),new Vector2(.5f,.5f),100,0,SpriteMeshType.FullRect,circle?Vector4.zero:new Vector4(16,16,16,16));sprites[key]=sprite;}return sprite;}
