  void HelpButton(string name,Transform parent,RectData rect,string value,UnityEngine.Events.UnityAction action){var image=Panel(name,parent,rect,Art.Hex("466C82"));image.sprite=PanelSprite(true);image.type=Image.Type.Simple;image.raycastTarget=true;var button=image.gameObject.AddComponent<Button>();button.targetGraphic=image;button.onClick.AddListener(action);var t=HelpText(name+" label",image.transform,new RectData{x=0,y=0,w=rect.w,h=rect.h},value,20,Art.Hex("FFF4DB"),true);t.rectTransform.anchorMin=Vector2.zero;t.rectTransform.anchorMax=Vector2.one;t.rectTransform.offsetMin=t.rectTransform.offsetMax=Vector2.zero;t.alignment=TextAnchor.MiddleCenter;t.fontSize=22;}
