  void OutsideBackground(){
   // Sidebars use one small reusable gradient, rather than retaining a full-screen texture per window size.
   if(AppRect.x<=.5f)return;const string key="outside-gradient";
   if(!sprites.TryGetValue(key,out var sprite)){var texture=new Texture2D(32,128,TextureFormat.RGBA32,false);var pixels=new Color32[32*128];Color a=Art.Hex("5A8495"),b=Art.Hex("28495D"),c=Art.Hex("1D3448");for(int y=0;y<128;y++)for(int x=0;x<32;x++){float t=Mathf.Sqrt(Mathf.Pow((x/31f-.5f)*.55f,2)+Mathf.Pow((1-y/127f-.25f)/1.06066f,2));pixels[y*32+x]=t<.75f?Color.Lerp(a,b,t/.75f):Color.Lerp(b,c,(t-.75f)/.25f);}texture.SetPixels32(pixels);texture.Apply();sprite=Sprite.Create(texture,new Rect(0,0,32,128),new Vector2(.5f,.5f),100);sprites[key]=sprite;}
   foreach(bool right in new[]{false,true}){float w=AppRect.x;var frame=Frame(right?"Right sidebar":"Left sidebar",root,false);frame.sizeDelta=new Vector2(w,height);frame.anchoredPosition=new Vector2((right?1:-1)*(width-w)/2,0);var image=frame.gameObject.AddComponent<Image>();image.sprite=sprite;image.raycastTarget=false;}
  }
  static bool FieldAllowed(string view,string id){if(view=="game")return id!="hint"&&id!="powerLabel"&&id!="powerValue"&&id!="pullInstructions"&&id!="coins";if(view=="home")return id=="homeCoins"||id=="homeSwaps";if(view=="shop")return id=="shopNote";if(view=="win"||view=="fail")return id=="resultBody"||id=="resultReward"||id=="stars";return false;}
  static bool Allowed(string view,string id){if(view=="home")return id=="play"||id=="homeShop"||id=="homeTab"||id=="homeSettings";if(view=="game")return id=="settings"||id=="gameShop"||id=="swap";if(view.StartsWith("settings"))return id=="closeSettings"||id=="sound"||id=="motion"||id=="resume"||(view=="settingsGame"&&(id=="restart"||id=="goHome"));if(view=="shop")return id=="closeShop"||id=="shopBuy";return id=="continue"||id=="resultHome";}
  void MakeButton(string view,Transform parent,ButtonData spec){var r=Frame(Names.ContainsKey(spec.id)?Names[spec.id]:spec.id,parent,false);Place(r,spec.rect);var hit=r.gameObject.AddComponent<Image>();hit.color=Color.clear;var b=r.gameObject.AddComponent<Button>();var bg=ImageAt("CSS button",r,new RectData{x=0,y=0,w=spec.rect.w+16,h=spec.rect.h+16},null);bg.rectTransform.anchorMin=bg.rectTransform.anchorMax=new Vector2(.5f,.5f);bg.rectTransform.anchoredPosition=Vector2.zero;bg.rectTransform.sizeDelta=new Vector2((spec.rect.w+16)*sx,(spec.rect.h+16)*sy);b.targetGraphic=bg;b.transition=Selectable.Transition.SpriteSwap;b.spriteState=new SpriteState{disabledSprite=null};b.onClick.AddListener(()=>Act(spec.id));buttons[view+"/"+spec.id]=b;buttonImages[view+"/"+spec.id]=bg;buttonSpecs[view+"/"+spec.id]=spec;b.gameObject.AddComponent<HtmlButtonFeedback>().Artwork=bg.rectTransform;if(view=="win"&&spec.id=="continue"){bg.sprite=PanelSprite(true);bg.type=Image.Type.Sliced;bg.color=Art.Hex("70935E");var o=new GameObject("Campaign continue label",typeof(RectTransform),typeof(CanvasRenderer),typeof(CrispText));o.layer=5;o.transform.SetParent(bg.transform,false);var lr=o.GetComponent<RectTransform>();lr.anchorMin=Vector2.zero;lr.anchorMax=Vector2.one;lr.offsetMin=lr.offsetMax=Vector2.zero;var label=o.GetComponent<Text>();label.font=font;label.fontSize=Mathf.Max(12,Mathf.RoundToInt(22*sx));label.fontStyle=FontStyle.Bold;label.color=Art.Hex("FFF1CE");label.alignment=TextAnchor.MiddleCenter;label.raycastTarget=false;label.text="SONRAKİ BÖLÜM";fields[view+"/continue"]=label;}}
  void Act(string id){if(PinPopSplash.Visible)return;switch(id){case "play":case "homeTab":game.GetComponent<AdventureHUD>().ShowMap();break;case "homeShop":case "gameShop":owner.ShowShop();break;case "homeSettings":case "settings":owner.ShowSettings();break;case "closeSettings":case "closeShop":case "resume":owner.CloseOverlays();break;case "sound":game.ToggleSound();break;case "motion":game.ToggleReducedMotion();break;case "restart":owner.PlayLevel(game.Level);break;case "goHome":case "resultHome":owner.ReturnHome();break;case "swap":if(game.SwapCredits>0)game.Swap();else owner.ShowSwapShop();break;case "continue":if(game.Won&&AdventureRules.FinalLevel(game.Level)){owner.ReturnHome();game.GetComponent<AdventureHUD>().ShowMap();}else owner.PlayLevel(game.Won?game.Level+1:game.Level);break;}}
  public void Refresh(){if(profile==null)return;foreach(var privacy in adPrivacyButtons)privacy.gameObject.SetActive(game.RewardedVideo!=null&&game.RewardedVideo.PrivacyRequired);if(game.ReducedMotion)foreach(var view in views.Values){var group=view.GetComponent<CanvasGroup>();if(group!=null)group.alpha=1;}Set("game/level",GameLocalization.Format("BÖLÜM {0}",game.Level+1));Set("game/moves",game.Moves.ToString());SetCoin("game/coins",game.Coins);SetCoin("home/homeCoins",game.Coins);SetCoin("shop/shopCoins",game.Coins);Set("shop/shopSwaps",GameLocalization.Format("Swap: <b>{0}</b>",game.SwapCredits));ReflowShop();Set("shop/shopNote",game.Coins<10?"Her zafer 30 coin kazandırır. Bir swap hakkı 10 coin.":"Haklar oyunu kapatsan da seninle kalır.");Set("game/swapCount",GameLocalization.Format("{0} hak",game.SwapCredits));fields["game/moves"].color=game.Moves<=2?Art.Hex("FFDB61"):Parse(FindField("game","moves").color);
   foreach(var kv in buttons){string id=kv.Value.name;bool active=true;if(id=="BUY_SWAP"||id=="SHOP_BUY")active=!game.IsPulling&&!game.Busy&&!game.Finished&&!game.Transitioning&&game.Coins>=10;if(id=="SWAP")active=!game.IsPulling&&!game.Busy&&!game.Finished&&!game.Transitioning&&game.Moves>0;if(id=="GAME_SHOP")active=!game.Busy&&!game.Finished;kv.Value.interactable=active;var spec=buttonSpecs[kv.Key];if(!crispReady&&(spec.id=="sound"||spec.id=="motion")){bool on=spec.id=="sound"?!game.Muted:game.ReducedMotion;buttonImages[kv.Key].sprite=SpriteFor(on&&!string.IsNullOrEmpty(spec.alt)?spec.alt:spec.normal);}}
   int nextOffset=game.Busy?0:1;bool any=false;for(int i=0;i<3;i++){int index=i+nextOffset;bool show=game.Moves>index&&game.Queue.Count>index&&!game.Finished;NextBalls[i].gameObject.SetActive(show);NextNumbers[i].gameObject.SetActive(show);if(show){any=true;NextColors[i]=game.Queue[index];NextBalls[i].sprite=BallLooks.Icon(game.SelectedBall,NextColors[i],Mathf.CeilToInt(NextBalls[i].rectTransform.rect.width));}}nextTitle.gameObject.SetActive(any);RefreshEconomyUI();RefreshRecoveryUI();SetPower(game.PullPower);RefreshCrispUI();
  }
  public void SetPower(float value){if(instructions==null)return;instructions.text="";}
  public void Home(bool value){home=value;if(toast!=null)toast.text="";overlay="";UpdateVisible();Refresh();}public void Overlay(string value){overlay=value;UpdateVisible();Refresh();if(!string.IsNullOrEmpty(value))FadeOverlay(views[value]);}void UpdateVisible(){game.Camera.GetComponent<HtmlLook>().ModalBlur=string.IsNullOrEmpty(overlay)?0:1.5f;foreach(var pair in views)pair.Value.gameObject.SetActive(pair.Key==(home?"home":"game")||pair.Key==overlay);if(!string.IsNullOrEmpty(overlay)&&views.ContainsKey(overlay))views[overlay].SetAsLastSibling();}
  public void Result(bool won){recoveryMessage="";resultWin=won;overlay=won?"win":"fail";UpdateVisible();Set(overlay+"/continue",won&&AdventureRules.FinalLevel(game.Level)?"HARİTAYA DÖN":won?"SONRAKİ BÖLÜM":"TEKRAR DENE");Set(overlay+"/resultBody",won?GameLocalization.Format("{0} duba toplandı.\n{1} hamle cebinde kaldı!",game.Total,game.Moves):GameLocalization.Format("{0} duba kaldı.\n{1}",game.Total-game.Cleared,"Doğru renk için sıranı değiştir."));Set(overlay+"/resultReward",won?GameLocalization.Format("+{0} COIN · Bakiye: {1}",game.LastReward,PinPopEconomy.Compact(game.Coins))+"\n<size="+Mathf.Max(11,Mathf.RoundToInt(12*AppRect.width/600))+">"+(game.LastReward==0?GameLocalization.Text("Bu bölümün ödülü zaten alındı."):game.VideoRescueUsed?GameLocalization.Text("Video desteğiyle tamamlandı"):game.LastBaseReward>0?GameLocalization.Format("Bölüm {0} + hamle bonusu {1}",game.LastBaseReward,game.LastMoveReward):GameLocalization.Format("Yeni rekor bonusu +{0}",game.LastMoveReward))+"</size>":"Coin ve swap hakların korunuyor.");RefreshRecoveryUI();int earned=won?(game.BonusMoves>=2?3:game.BonusMoves==1?2:1):0;if(stars.TryGetValue(overlay,out var list))for(int i=0;i<3;i++){list[i].text=i<earned?"★":"☆";StartCoroutine(StarReveal(list[i].transform,i));}FadeOverlay(views[overlay]);if(won){NativeResult();fireworks.Restart();flyingCoins.Restart();}}
  public void HideResult(){if(overlay=="win"||overlay=="fail")overlay="";UpdateVisible();}public void Toast(string text,float seconds){toast.text=text;toastUntil=Time.unscaledTime+seconds;}public void Banner(string text){if(game.ReducedMotion)return;banner.text=text;StartCoroutine(ClearBanner());}IEnumerator ClearBanner(){yield return new WaitForSecondsRealtime(.7f);banner.text="";}
  public void Curtain(bool show,int level=-1){if(show&&!curtainShown)curtainStarted=Time.unscaledTime;curtainShown=show;if(level>=0)transitionLevel=level;if(show)curtain.Show(transitionLevel,game.ReducedMotion,curtainStarted);else curtain.gameObject.SetActive(false);}public void PopQueue(){if(game.ReducedMotion)return;foreach(var b in NextBalls)if(b.gameObject.activeSelf)StartCoroutine(Pop(b.transform));}IEnumerator Pop(Transform t){for(float x=0;x<.18f;x+=Time.unscaledDeltaTime){if(t==null)yield break;if(game.ReducedMotion)break;t.localScale=Vector3.one*(1+Mathf.Sin(x/.18f*Mathf.PI)*.12f);yield return null;}if(t!=null)t.localScale=Vector3.one;}
  HtmlResultFX CreateResultFX(Transform parent,bool coins,Rect card){var fx=CreateInactiveGraphic<HtmlResultFX>(coins?"Flying reward coins":"Victory fireworks",parent);Place(fx.rectTransform,profile.app);var wallet=FindField("game","coins").rect;fx.Build(game,coins,new Vector2((wallet.x+wallet.w/2-profile.app.x)*600/profile.app.w,(wallet.y+wallet.h/2-profile.app.y)*1000/profile.app.h),card);fx.gameObject.SetActive(true);return fx;}
  Image WalletImage(string id,Transform parent){var image=ImageAt(id,parent,Asset(id).rect,null);image.raycastTarget=false;return image;}
  void LayoutWallet(string id,int value){if(crispReady)return;if(!walletImages.TryGetValue(id,out var image)||!fields.TryGetValue(id,out var label))return;string view=id.StartsWith("game/")?"game":"home",field=id.Substring(id.IndexOf('/')+1);var data=FindField(view,field);var settings=label.GetGenerationSettings(Vector2.zero);float numericWidth=label.cachedTextGeneratorForLayout.GetPreferredWidth(PinPopEconomy.Compact(value),settings)/label.pixelsPerUnit;float extra=Mathf.Max(0,numericWidth/sx-data.rect.w);string assetId=id=="game/coins"?"wallet":id=="home/homeCoins"?"home-wallet":"home-swaps";var asset=Asset(assetId);bool right=id=="home/homeSwaps";var rect=new RectData{x=asset.rect.x-(right?extra:0),y=asset.rect.y,w=asset.rect.w+extra,h=asset.rect.h};Place(image.rectTransform,Expand(rect,asset.pad));Place(label.rectTransform,new RectData{x=data.rect.x-(right?extra:0),y=data.rect.y,w=Mathf.Max(data.rect.w,label.preferredWidth/sx),h=data.rect.h});}
  void BuildShopMeta(){var asset=Asset("shop-meta");var coin=FindField("shop","shopCoins");var swap=FindField("shop","shopSwaps");fields["shop/shopCoins"]=Label("Shop coin total",views["shop"],asset.rect,Mathf.RoundToInt(coin.size*sx),Parse(coin.color),false);fields["shop/shopSwaps"]=Label("Shop swap total",views["shop"],asset.rect,Mathf.RoundToInt(swap.size*sx),Parse(swap.color),false);}
  void ReflowShop(){if(!fields.TryGetValue("shop/shopCoins",out var coin)||!fields.TryGetValue("shop/shopSwaps",out var swap))return;var rect=Asset("shop-meta").rect;float a=coin.preferredWidth/sx,b=swap.preferredWidth/sx,start=rect.x+(rect.w-a-b-18)/2;Place(coin.rectTransform,new RectData{x=start,y=rect.y,w=a,h=rect.h});Place(swap.rectTransform,new RectData{x=start+a+18,y=rect.y,w=b,h=rect.h});}
  void DisplayCoin(string id,Text label,int value){coinDisplayed[id]=value;label.text=id=="shop/shopCoins"?GameLocalization.Format("Coin: <b>{0}</b>",PinPopEconomy.Compact(value)):PinPopEconomy.Compact(value);if(id=="shop/shopCoins")ReflowShop();else LayoutWallet(id,value);}
  void SetCoin(string id,int target){if(!fields.TryGetValue(id,out var label))return;if(!coinDisplayed.ContainsKey(id)){coinTargets[id]=target;DisplayCoin(id,label,target);return;}if(coinTargets.TryGetValue(id,out int previous)&&previous==target)return;coinTargets[id]=target;if(coinAnimations.TryGetValue(id,out var old)&&old!=null)StopCoroutine(old);if(game.ReducedMotion){DisplayCoin(id,label,target);return;}coinDisplayed.TryGetValue(id,out int from);coinAnimations[id]=StartCoroutine(Counter(id,label,from,target));}
  IEnumerator Counter(string id,Text label,int from,int target){for(float t=0;t<.45f;t+=Time.unscaledDeltaTime){if(label==null)yield break;if(game.ReducedMotion)break;DisplayCoin(id,label,Mathf.RoundToInt(Mathf.Lerp(from,target,1-Mathf.Pow(1-t/.45f,3))));yield return null;}if(label!=null)DisplayCoin(id,label,target);}
  void FadeOverlay(RectTransform view){var group=view.GetComponent<CanvasGroup>()??view.gameObject.AddComponent<CanvasGroup>();StartCoroutine(Fade(group));}
  IEnumerator Fade(CanvasGroup group){if(!game.ReducedMotion)for(float t=0;t<.18f;t+=Time.unscaledDeltaTime){if(group==null)yield break;if(game.ReducedMotion)break;group.alpha=t/.18f;yield return null;}if(group!=null)group.alpha=1;}
  IEnumerator StarReveal(Transform star,int index){if(game.ReducedMotion){star.localScale=Vector3.one;yield break;}star.localScale=Vector3.zero;yield return new WaitForSecondsRealtime(.15f+index*.15f);for(float t=0;t<.5f;t+=Time.unscaledDeltaTime){if(star==null)yield break;if(game.ReducedMotion)break;float p=t/.5f;star.localScale=Vector3.one*(1+2.18f*Mathf.Pow(p-1,3)+1.18f*Mathf.Pow(p-1,2));yield return null;}if(star!=null)star.localScale=Vector3.one;}
  public void RescueEffect(){if(!game.ReducedMotion&&fields.TryGetValue("game/moves",out var moves))StartCoroutine(Pop(moves.transform));Banner("+3 HAMLE!");}
  public void CountEffect(){if(!game.ReducedMotion&&fields.TryGetValue("game/count",out var count))StartCoroutine(Pop(count.transform));}
  public void PurchaseEffect(){if(!game.ReducedMotion&&ShopVisible&&buttons.TryGetValue("shop/shopBuy",out var buy))StartCoroutine(Pop(buy.transform));}
