  FieldData FindField(string view,string id){return Array.Find(Array.Find(profile.views,v=>v.id==view).fields,f=>f.id==id);}AssetData Asset(string id){return Array.Find(profile.assets,a=>a.id==id);}void Set(string id,string value){if(fields.TryGetValue(id,out var t))t.text=value;}
  Sprite SpriteFor(string name){if(string.IsNullOrEmpty(name))return null;if(!sprites.TryGetValue(name,out var sprite)){var texture=Resources.Load<Texture2D>("HtmlReference/"+name);sprite=Sprite.Create(texture,new Rect(0,0,texture.width,texture.height),new Vector2(.5f,.5f),100,0,SpriteMeshType.FullRect);sprite.name=name;sprites[name]=sprite;}return sprite;}
  // Build custom graphics while inactive so GraphicRegistry never sees an unfinished UI object.
  T CreateInactiveGraphic<T>(string name,Transform parent) where T:Graphic {
   var obj=new GameObject(name,typeof(RectTransform),typeof(CanvasRenderer));obj.SetActive(false);obj.layer=5;
   obj.transform.SetParent(parent,false);return obj.AddComponent<T>();
  }
  RectTransform Frame(string name,Transform parent,bool full=true){var obj=new GameObject(name,typeof(RectTransform));obj.layer=5;var r=obj.GetComponent<RectTransform>();r.SetParent(parent,false);if(full){r.anchorMin=Vector2.zero;r.anchorMax=Vector2.one;r.offsetMin=r.offsetMax=Vector2.zero;}return r;}
  void Place(RectTransform r,RectData at){r.anchorMin=r.anchorMax=new Vector2(.5f,.5f);r.sizeDelta=new Vector2(at.w*sx,at.h*sy);r.anchoredPosition=new Vector2(ox+(at.x+at.w/2)*sx-width/2,height/2-oy-(at.y+at.h/2)*sy);}
