  static RectData Expand(RectData r,float pad){return new RectData{x=r.x-pad,y=r.y-pad,w=r.w+pad*2,h=r.h+pad*2};}static Color Parse(string css){var values=System.Text.RegularExpressions.Regex.Matches(css,"[0-9.]+");return values.Count>=3?new Color(float.Parse(values[0].Value,System.Globalization.CultureInfo.InvariantCulture)/255,float.Parse(values[1].Value,System.Globalization.CultureInfo.InvariantCulture)/255,float.Parse(values[2].Value,System.Globalization.CultureInfo.InvariantCulture)/255,values.Count>3?float.Parse(values[3].Value,System.Globalization.CultureInfo.InvariantCulture):1):Color.white;}
